import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.runners.MockitoJUnitRunner;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

@RunWith(MockitoJUnitRunner.class)
public class CommentsConfigurationTest {

    @Test
    public void commentsConfigurationEmptyConstructorTest() {
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();
        assertTrue(commentsConfiguration.getAllComments().isEmpty());
    }

    @Test
    public void commentsConfigurationConstructorWithParamsTest() {
        List<String> commentLines = Arrays.asList("Line 1", "Line 2");
        Map<String, List<String>> comments = Collections.singletonMap("path1", commentLines);
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration(comments);
        assertEquals(commentLines, commentsConfiguration.getAllComments().get("path1"));
    }

    @Test
    public void setCommentTest() {
        String path = "path1";
        String[] commentLines = {"Line 1", "Line 2"};
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();
        commentsConfiguration.setComment(path, commentLines);
        assertEquals(Arrays.asList(commentLines), commentsConfiguration.getAllComments().get(path));
    }

    @Test
    public void getAllCommentsTest() {
        String path = "path1";
        String[] commentLines = {"Line 1", "Line 2"};
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();
        commentsConfiguration.setComment(path, commentLines);
        Map<String, List<String>> allComments = commentsConfiguration.getAllComments();
        assertEquals(allComments.get(path), Arrays.asList(commentLines));
    }

    @Test
    public void setCommentOverrideTest() {
        String path = "path1";
        String[] commentLines1 = {"Line 1", "Line 2"};
        String[] commentLines2 = {"Line 3", "Line 4"};
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();
        commentsConfiguration.setComment(path, commentLines1);
        commentsConfiguration.setComment(path, commentLines2);
        assertEquals(Arrays.asList(commentLines2), commentsConfiguration.getAllComments().get(path));
    }
}
